// Subject-specific teaching models. Values are invented examples, never personal advice.
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (v,d=1) => Number(v.toFixed(d)).toLocaleString();
const slider = (name,label,min,max,value,step=1) => `<label class="lab-control">${label}<input type="range" data-input="${name}" min="${min}" max="${max}" value="${value}" step="${step}"><output data-value="${name}">${value}</output></label>`;
const value = (root,key) => Number(root.querySelector(`[data-input="${key}"]`).value);
const controls = root => root.querySelectorAll('[data-input]').forEach(input=>{const out=root.querySelector(`[data-value="${input.dataset.input}"]`);if(out)out.textContent=input.value;});
const reset = '<button type="button" class="text-button" data-lab-reset>Reset model</button>';
const frame = (body, note) => `<div class="subject-lab">${body}<p class="lw-note">${note}</p></div>`;
const stat = (label,val) => `<span><strong>${val}</strong>${label}</span>`;

export function macroEnergy(carbohydrate,protein,fat,servings=1){
 const parts=[carbohydrate*4*servings,protein*4*servings,fat*9*servings];
 return {parts,total:parts.reduce((a,b)=>a+b,0)};
}
const nutritionlab={
 label:'Food-energy laboratory',
 render:()=>frame(`<p>Predict the total energy before revealing it. Change the macronutrients per serving, then explore what a second serving changes.</p><div class="lab-controls">${slider('carb','Carbohydrate per serving (g)',0,80,30)}${slider('protein','Protein per serving (g)',0,50,10)}${slider('fat','Fat per serving (g)',0,40,10)}${slider('servings','Number of servings',0.5,4,1,0.5)}</div><div class="macro-bars" role="img" aria-label="Relative energy contributed by carbohydrate, protein and fat"><div data-bar="0"><span>Carbohydrate</span></div><div data-bar="1"><span>Protein</span></div><div data-bar="2"><span>Fat</span></div></div><label class="lab-prediction">Your energy estimate (kcal)<input type="number" min="0" step="any" data-estimate placeholder="Enter a prediction"></label><div class="lw-actions"><button type="button" class="button" data-reveal>Check prediction</button>${reset}</div><div class="lab-answer" hidden><div class="lw-stats" data-stats></div><p data-formula></p><p class="lw-msg" aria-live="polite"></p></div>`, 'General factors: carbohydrate 4 kcal/g, protein 4 kcal/g, fat 9 kcal/g. Food-label values can differ because of fiber and rounding. This model does not prescribe energy needs.'),
 mount(root){
  const update=()=>{controls(root);const {parts,total}=macroEnergy(value(root,'carb'),value(root,'protein'),value(root,'fat'),value(root,'servings'));
   root.querySelectorAll('[data-bar]').forEach((bar,i)=>{bar.style.width=(total?parts[i]/total*100:0)+'%';bar.title=`${['Carbohydrate','Protein','Fat'][i]}: ${num(parts[i])} kcal`;});
   root.querySelector('[data-stats]').innerHTML=stat('total kcal',num(total))+stat('carbohydrate kcal',num(parts[0]))+stat('protein kcal',num(parts[1]))+stat('fat kcal',num(parts[2]));
   root.querySelector('[data-formula]').textContent=`(${value(root,'carb')} × 4 + ${value(root,'protein')} × 4 + ${value(root,'fat')} × 9) × ${value(root,'servings')} = ${num(total)} kcal.`;
   return total;
  };
  root.addEventListener('input',ev=>{if(ev.target.matches('[data-input]')){update();root.querySelector('.lab-answer').hidden=true;}});
  root.querySelector('[data-reveal]').addEventListener('click',()=>{const input=root.querySelector('[data-estimate]'),msg=root.querySelector('.lw-msg');if(!input.value||!input.checkValidity()){input.reportValidity();input.focus();return;}const total=update(),correct=Math.abs(Number(input.value)-total)<=0.5;root.querySelector('.lab-answer').hidden=false;msg.textContent=correct?'Correct. Now double the servings: which quantities double, and which proportions stay the same?':'Compare your estimate with the calculation. Multiply grams by energy per gram before multiplying by servings.';msg.dataset.state=correct?'good':'bad';});
  root.querySelector('[data-lab-reset]').addEventListener('click',()=>{root.querySelectorAll('[data-input]').forEach(i=>i.value=i.defaultValue);root.querySelector('[data-estimate]').value='';root.querySelector('.lab-answer').hidden=true;update();});update();
 }
};

const FLOW=[
 ['Identity','Match the fictional patient using approved identifiers. A valid message attached to the wrong person is still unsafe.'],
 ['Structure','A standard exchange format organizes fields so the receiving system can parse them. Structure alone does not make meanings equivalent.'],
 ['Meaning','Agree on the observation code and its units. A value of 98 means something different in °F and °C.'],
 ['Permission','Verify authorization and the permitted purpose before making the record available. Encryption does not replace access control.'],
 ['Acknowledgment','Confirm that the receiving system accepted the record; preserve an audit trail and surface any errors.']
];
const flowSvg=()=>`<svg class="lab-flow" viewBox="0 0 620 130" role="img" aria-label="Five checks along a health-information exchange"><path class="lab-link" d="M60 54H560"/>${FLOW.map(([name],i)=>`<g data-flow-step="${i}"><circle cx="${60+i*125}" cy="54" r="26"/><text x="${60+i*125}" y="60" text-anchor="middle">${i+1}</text><text class="lab-small" x="${60+i*125}" y="105" text-anchor="middle">${name}</text></g>`).join('')}</svg>`;
const informaticsflow={
 label:'Interoperability simulator',
 render:()=>frame(`<p>Follow a fictional temperature observation from one system to another. Introduce a failure and find which check should catch it.</p><label class="lab-control">Scenario<select data-fault><option value="none">Valid record</option><option value="0">Wrong patient identifier</option><option value="1">Missing required field</option><option value="2">Units omitted</option><option value="3">Unauthorized recipient</option></select></label>${flowSvg()}<div class="lab-step-summary" aria-live="polite"></div><div class="lw-actions"><button type="button" class="text-button" data-flow-back>← Back</button><button type="button" class="button" data-flow-next>Run first check →</button>${reset}</div>`, 'Conceptual workflow, not an implementation of FHIR or a legal determination. Real exchanges apply additional checks and organizational policies.'),
 mount(root){let at=-1;const draw=()=>{const fault=root.querySelector('[data-fault]').value,blocked=String(at)===fault;root.querySelectorAll('[data-flow-step]').forEach((n,i)=>{n.classList.toggle('visited',i<=at);n.classList.toggle('current',i===at);n.classList.toggle('blocked',i===at&&blocked);});root.querySelector('.lab-step-summary').innerHTML=at<0?'<p>Record: fictional patient SIM-104, temperature 37 °C. Select a scenario, then run the checks.</p>':`<h5>${blocked?'Stop and resolve: ':''}${esc(FLOW[at][0])}</h5><p>${esc(FLOW[at][1])}</p><p>${blocked?'This record must not proceed. Select the valid record scenario to retry.':at===4?'All five teaching checks complete. The receiving system acknowledged the record.':'Check complete. Advance to the next check.'}</p>`;root.querySelector('[data-flow-next]').disabled=blocked||at===4;root.querySelector('[data-flow-back]').disabled=at<0;root.querySelector('[data-flow-next]').textContent=at<0?'Run first check →':'Next check →';};root.querySelector('[data-flow-next]').addEventListener('click',()=>{at=Math.min(4,at+1);draw();});root.querySelector('[data-flow-back]').addEventListener('click',()=>{at=Math.max(-1,at-1);draw();});root.querySelector('[data-fault]').addEventListener('change',()=>{at=-1;draw();});root.querySelector('[data-lab-reset]').addEventListener('click',()=>{at=-1;root.querySelector('[data-fault]').value='none';draw();});draw();}
};

export function compareRates(beforeEvents,beforeTotal,afterEvents,afterTotal){
 const before=beforeEvents/beforeTotal*100,after=afterEvents/afterTotal*100;
 return {before,after,absolute:before-after,relative:before===0?null:(before-after)/before*100};
}
const qualitylab={
 label:'Quality-improvement laboratory',
 render:()=>frame(`<p>A clinic wants to reduce late follow-ups. Compare rates, not raw counts, when the number of eligible visits changes. The measure is late follow-ups per 100 eligible visits.</p><div class="lab-controls">${slider('beforeEvents','Late follow-ups before',0,40,20)}${slider('beforeTotal','Eligible visits before',50,400,100,10)}${slider('afterEvents','Late follow-ups after',0,40,15)}${slider('afterTotal','Eligible visits after',50,400,150,10)}</div><svg class="quality-chart" viewBox="0 0 600 210" role="img" aria-label="Before and after late-follow-up rates; maximum axis value 100 percent"><text x="10" y="50">Before</text><text x="10" y="125">After</text><rect class="quality-track" x="90" y="25" width="450" height="36"/><rect class="quality-track" x="90" y="100" width="450" height="36"/><rect class="quality-bar" data-rate-bar="before" x="90" y="25" width="0" height="36"/><rect class="quality-bar after" data-rate-bar="after" x="90" y="100" width="0" height="36"/><text x="90" y="175">0%</text><text x="540" y="175" text-anchor="end">100%</text><text data-rate-text="before" x="90" y="85"></text><text data-rate-text="after" x="90" y="155"></text></svg><div class="lw-stats" data-rate-stats aria-live="polite"></div><p>What can this comparison establish?</p><div class="lw-actions"><button class="chip" type="button" data-infer="cause">The intervention caused the change</button><button class="chip" type="button" data-infer="observe">The observed rates differ</button>${reset}</div><p class="lw-msg" aria-live="polite"></p>`, 'Invented counts. A before-and-after comparison alone cannot establish causation; inspect time trends, case mix, process measures and balancing measures.'),
 mount(root){const draw=()=>{controls(root);const r=compareRates(value(root,'beforeEvents'),value(root,'beforeTotal'),value(root,'afterEvents'),value(root,'afterTotal'));for(const key of ['before','after']){root.querySelector(`[data-rate-bar="${key}"]`).setAttribute('width',4.5*r[key]);root.querySelector(`[data-rate-text="${key}"]`).textContent=`${num(r[key])} per 100 visits`;}root.querySelector('[data-rate-stats]').innerHTML=stat('percentage-point reduction',num(r.absolute))+stat('relative reduction',r.relative===null?'Undefined':num(r.relative)+'%');root.querySelector('.lw-msg').textContent='';};root.addEventListener('input',draw);root.querySelectorAll('[data-infer]').forEach(b=>b.addEventListener('click',()=>{const ok=b.dataset.infer==='observe';const msg=root.querySelector('.lw-msg');msg.textContent=ok?'Yes. The rates describe these samples. Investigate design, variation, changes in population and other explanations before claiming causation.':'Not yet. A lower observed rate can have multiple explanations. Look for sustained change and evaluate alternative causes.';msg.dataset.state=ok?'good':'bad';}));root.querySelector('[data-lab-reset]').addEventListener('click',()=>{root.querySelectorAll('[data-input]').forEach(i=>i.value=i.defaultValue);draw();});draw();}
};

const STAGES=[
 {name:'Infancy',age:'Birth–1 year',physical:'Rapid growth and developing posture, reaching and movement. Abilities emerge across ranges rather than on a single deadline.',cognitive:'Learning through sensory experiences, repeated actions and responsive interaction. Communication begins well before spoken words.',social:'Responsive caregiving and co-regulation support attachment. Family routines and access to support shape experience.',support:'Respond to signals, provide safe opportunities to explore, and raise developmental concerns with an appropriate professional.'},
 {name:'Early childhood',age:'1–5 years',physical:'Growing coordination supports walking, manipulating objects and gradually more complex self-care.',cognitive:'Language and symbolic play expand. Young children benefit from concrete explanations and guided practice.',social:'Autonomy grows alongside a continuing need for predictable, supportive caregivers. Play provides practice in cooperation.',support:'Offer limited choices, model language, and scaffold tasks while respecting cultural context and individual differences.'},
 {name:'School age',age:'6–11 years',physical:'Motor skills and strength generally become more refined. Variation in size and maturation is expected.',cognitive:'Children increasingly reason about concrete situations and use deliberate learning strategies.',social:'Peer relationships, school participation and feelings of competence become influential.',support:'Break skills into achievable steps; provide specific feedback and equitable access to learning and participation.'},
 {name:'Adolescence',age:'12–18 years',physical:'Pubertal timing varies widely. Physical development and psychosocial maturity do not progress in lockstep.',cognitive:'Abstract thinking develops, while planning and regulation remain sensitive to experience, stress and context.',social:'Identity exploration, peer influence and growing autonomy coexist with a need for supportive relationships.',support:'Use respectful dialogue, invite the young person’s perspective, and support informed decision-making.'},
 {name:'Early adulthood',age:'19–39 years',physical:'Many physical capacities are well established, but health is shaped by environment, opportunity and behavior.',cognitive:'Experience and expertise develop; education and work pathways vary rather than following one universal sequence.',social:'Roles may include relationships, employment, caregiving or education in many combinations.',support:'Recognize individual goals, resources, constraints and cultural definitions of adulthood.'},
 {name:'Middle adulthood',age:'40–64 years',physical:'Gradual biological changes can coexist with strong functional capacity. Chronological age alone predicts little about one individual.',cognitive:'Accumulated knowledge and expertise often support complex tasks; stress and health can affect performance.',social:'Work transitions, care responsibilities and community participation vary considerably.',support:'Build on strengths, adapt environments and distribute support rather than assuming every person has the same obligations.'},
 {name:'Later adulthood',age:'65+ years',physical:'Sensory, strength and mobility changes vary. Disease, disability and dependence are not inevitable consequences of age.',cognitive:'Processing speed may change while accumulated knowledge remains valuable. Acute confusion requires assessment and is not simply normal aging.',social:'Relationships, purpose, autonomy and accessible surroundings remain important. Loss and growth can both occur.',support:'Ask about preferences and abilities; support autonomy, participation and accommodations rather than using age-based stereotypes.'}
];
const lifespan={
 label:'Lifespan explorer',
 render:()=>frame(`<p>Select a life period, then compare physical, cognitive and social development. These broad teaching bands are not diagnostic milestone cutoffs.</p><div class="life-tabs" role="group" aria-label="Life period">${STAGES.map((s,i)=>`<button type="button" class="chip" data-stage="${i}" aria-pressed="false">${s.name}</button>`).join('')}</div><svg viewBox="0 0 600 80" class="life-track" role="img" aria-label="Selected period on a lifespan sequence, not to time scale"><path d="M30 35H570"/>${STAGES.map((s,i)=>`<circle data-age-dot="${i}" cx="${30+i*90}" cy="35" r="9"/>`).join('')}<circle data-life-marker cx="30" cy="35" r="15"/></svg><div class="life-detail" aria-live="polite"></div><div class="lw-actions"><button type="button" class="button secondary" data-compare>Compare with the next period</button>${reset}</div><div class="life-comparison" hidden></div>`, 'Development is multidimensional, lifelong and influenced by culture, relationships, biology and resources. Stage theories are organizing frameworks, not predictions for every individual.'),
 mount(root){let at=0;const describe=s=>`<h5>${esc(s.name)} <small>${esc(s.age)}</small></h5><dl>${['physical','cognitive','social','support'].map(k=>`<div><dt>${k[0].toUpperCase()+k.slice(1)}</dt><dd>${esc(s[k])}</dd></div>`).join('')}</dl>`;const draw=()=>{root.querySelectorAll('[data-stage]').forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===at));b.classList.toggle('on',i===at);});root.querySelector('[data-life-marker]').setAttribute('cx',String(30+at*90));root.querySelector('.life-detail').innerHTML=describe(STAGES[at]);root.querySelector('.life-comparison').hidden=true;root.querySelector('[data-compare]').textContent=at===6?'Compare with the previous period':'Compare with the next period';};root.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>{at=Number(b.dataset.stage);draw();}));root.querySelector('[data-compare]').addEventListener('click',()=>{const box=root.querySelector('.life-comparison');box.innerHTML=describe(STAGES[at===6?5:at+1]);box.hidden=!box.hidden;});root.querySelector('[data-lab-reset]').addEventListener('click',()=>{at=0;draw();});draw();}
};

const WORDS=[
 {word:'bradycardia',parts:['brady-','cardi','-ia'],meanings:['slow','heart','condition'],meaning:'A condition of slow heart rate. The term alone does not establish its cause or clinical significance.'},
 {word:'hyperglycemia',parts:['hyper-','glyc','-emia'],meanings:['above normal','sugar','blood condition'],meaning:'Elevated glucose in the blood. Recognizing the word does not replace measurement and clinical interpretation.'},
 {word:'gastritis',parts:['','gastr','-itis'],meanings:['no prefix','stomach','inflammation'],meaning:'Inflammation of the stomach. The suffix describes inflammation, not necessarily infection.'},
 {word:'nephrectomy',parts:['','nephr','-ectomy'],meanings:['no prefix','kidney','surgical removal'],meaning:'Surgical removal of a kidney or kidney tissue, depending on the specified procedure. Do not confuse removal with incision (-otomy).'},
 {word:'hypothermia',parts:['hypo-','therm','-ia'],meanings:['below normal','heat / temperature','condition'],meaning:'A condition of abnormally low body temperature. This is different from feeling cold without a measured temperature change.'}
];
const termlab={
 label:'Word anatomy explorer',
 render:(w={})=>frame(`<p>Select a term. Uncover its suffix first, then the root and prefix. Predict a plain-language meaning before opening the interpretation.</p><label class="lab-control">Term<select data-word>${(w.words||WORDS).map((w,i)=>`<option value="${i}">${w.word}</option>`).join('')}</select></label><div class="term-anatomy"></div><p class="term-detail" aria-live="polite"></p><div class="lw-actions"><button type="button" class="button secondary" data-interpret>Reveal interpretation</button>${reset}</div><p class="term-interpretation" hidden></p>`, 'Word parts help decode unfamiliar terms, but do not always predict a term’s accepted clinical meaning. Confirm the complete word in the official reference.'),
 mount(root,config={}){const words=config.words||WORDS;let at=0;const draw=()=>{const w=words[at];root.querySelector('.term-anatomy').innerHTML=w.parts.map((p,i)=>`<button type="button" data-piece="${i}" aria-pressed="false"><small>${['Prefix','Root','Suffix'][i]}</small><strong>${esc(p||'—')}</strong><span hidden>${esc(w.meanings[i])}</span></button>`).join('');root.querySelector('.term-detail').textContent='Start with the suffix, then identify what body part or process it modifies.';root.querySelector('.term-interpretation').hidden=true;root.querySelector('.term-interpretation').textContent=w.meaning;};root.addEventListener('click',ev=>{const b=ev.target.closest('[data-piece]');if(!b)return;const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));b.querySelector('span').hidden=!on;root.querySelector('.term-detail').textContent=`${['Prefix','Root','Suffix'][b.dataset.piece]}: ${words[at].meanings[b.dataset.piece]}.`;});root.querySelector('[data-word]').addEventListener('change',ev=>{at=Number(ev.target.value);draw();});root.querySelector('[data-interpret]').addEventListener('click',()=>{root.querySelector('.term-interpretation').hidden=false;});root.querySelector('[data-lab-reset]').addEventListener('click',()=>{at=0;root.querySelector('[data-word]').value='0';draw();});draw();}
};

export const SUBJECT_LABS={nutritionlab,informaticsflow,qualitylab,lifespan,termlab};
